<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {request,RequestError} from '../../../api/client'
import {useSession} from '../../../stores/session'
import type {components} from '../../../api/generated/schema'
import {ElTable,ElTableColumn,ElButton,ElInput,ElInputNumber,ElTag} from 'element-plus'
import 'element-plus/dist/index.css'
type Balance=components['schemas']['Inventory']
const items=ref<Balance[]>([]),ledger=ref<components['schemas']['Ledger'][]>([]),next=ref(''),ledgerNext=ref(''),q=ref(''),low=ref(false),busy=ref(false),error=ref(''),selected=ref<Balance>(),warning=ref(0),ledgerProduct=ref(''),store=useSession()
const canWrite=computed(()=>store.session?.permissions.includes('inventory.write'))
const pending=ref<{path:string;body:string;key:string}>()
function message(e:unknown){return e instanceof RequestError?({'VERSION_CONFLICT':'库存已变化，请刷新后重新设置','IDEMPOTENCY_CONFLICT':'请求标识冲突，请刷新后重试','FORBIDDEN':'没有库存操作权限'}[e.detail.code]??'操作失败，请重试'):'网络异常，可重试原请求'}
async function load(after=''){busy.value=true;error.value='';try{const p=new URLSearchParams({limit:'20',q:q.value,status:low.value?'LOW':''});if(after)p.set('after_id',after);const result=await request<components['schemas']['InventoryList']>('/api/v1/admin/inventory?'+p);items.value=result.items;next.value=result.next_after_id??''}catch(e){error.value=message(e)}finally{busy.value=false}}
function edit(b:Balance){if(pending.value)return;selected.value=b;warning.value=b.warning_level}
async function save(){if(!selected.value)return;busy.value=true;error.value='';if(!pending.value)pending.value={path:'/api/v1/admin/inventory/'+selected.value.product_id+'/warning',body:JSON.stringify({version:selected.value.version,warning_level:warning.value}),key:crypto.randomUUID()};try{await request(pending.value.path,{method:'PATCH',body:pending.value.body},pending.value.key);pending.value=undefined;selected.value=undefined;await load()}catch(e){error.value=message(e);if(e instanceof RequestError&&e.status<500){pending.value=undefined;if(e.status===409)selected.value=undefined}}finally{busy.value=false}}
async function loadLedger(product=ledgerProduct.value,after=''){busy.value=true;error.value='';ledgerProduct.value=product;try{const p=new URLSearchParams({limit:'20'});if(product)p.set('product_id',product);if(after)p.set('after_id',after);const result=await request<components['schemas']['LedgerList']>('/api/v1/admin/inventory/transactions?'+p);ledger.value=result.items;ledgerNext.value=result.next_after_id??''}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><main class="admin-page"><div class="page-title"><h1>库存余额</h1><RouterLink to="/admin">工作台</RouterLink><RouterLink to="/admin/inventory/documents">入出库单</RouterLink></div><form class="filters" @submit.prevent="load()"><ElInput v-model="q" maxlength="100" placeholder="商品名称或编码" aria-label="搜索商品"/><label><input v-model="low" type="checkbox">仅低库存</label><ElButton native-type="submit" :loading="busy">查询</ElButton></form><p v-if="error" role="alert">{{error}}</p><ElTable :data="items" empty-text="暂无库存记录"><ElTableColumn prop="product_id" label="商品 ID"/><ElTableColumn prop="on_hand" label="实际库存"/><ElTableColumn prop="reserved" label="已预占"/><ElTableColumn prop="available" label="可用库存"/><ElTableColumn label="警戒值"><template #default="{row}">{{row.warning_level}} <ElTag v-if="row.available<=row.warning_level" type="warning">低库存</ElTag></template></ElTableColumn><ElTableColumn label="操作"><template #default="{row}"><ElButton :disabled="busy" @click="loadLedger(row.product_id)">流水</ElButton><ElButton v-if="canWrite" :disabled="busy||!!pending" @click="edit(row)">设置警戒值</ElButton></template></ElTableColumn></ElTable><ElButton v-if="next" :disabled="busy" @click="load(next)">下一页</ElButton><ElButton :disabled="busy" @click="load()">刷新 / 首页</ElButton><form v-if="selected" class="filters" @submit.prevent="save"><label>商品 {{selected.product_id}} 警戒值 <ElInputNumber v-model="warning" :min="0" :max="1000000" :precision="0" :disabled="!!pending"/></label><ElButton native-type="submit" :loading="busy">{{pending?'重试原请求':'保存'}}</ElButton><ElButton v-if="!pending" @click="selected=undefined">取消</ElButton></form><h2>库存流水 {{ledgerProduct? '· 商品 '+ledgerProduct:''}}</h2><ElButton :disabled="busy" @click="loadLedger('')">全部流水</ElButton><ElTable :data="ledger" empty-text="暂无流水"><ElTableColumn prop="product_id" label="商品 ID"/><ElTableColumn prop="on_hand_delta" label="实际库存变动"/><ElTableColumn prop="reserved_delta" label="预占变动"/><ElTableColumn prop="event_key" label="事件"/><ElTableColumn prop="reason" label="原因"/><ElTableColumn prop="created_at" label="时间"/></ElTable><ElButton v-if="ledgerNext" :disabled="busy" @click="loadLedger(ledgerProduct,ledgerNext)">下一页流水</ElButton></main></template>
